import { useState, useEffect } from "react";

function PostList({ selectedPost, onSelectPost, reload, categoryId }) {
    const [posts, setPosts] = useState([]);

    useEffect(() => {
        const fetchPosts = async () => {
            try {
                let url = "http://localhost:5000/api/posts";
                if (categoryId) url += `?category_id=${categoryId}`;

                const res = await fetch(url);
                const data = await res.json();
                setPosts(data);
            } catch (err) {
                console.error("Помилка при завантаженні постів:", err);
            }
        };

        fetchPosts();
    }, [reload, categoryId]);

    if (!categoryId) {
        return <p className="text-gray-500">Оберіть категорію для перегляду постів</p>;
    }

    return (
        <div className="space-y-4">
            {posts.length === 0 ? (
                <p className="text-gray-500">Пости відсутні в цій категорії</p>
            ) : (
                <ul className="space-y-3">
                    {posts.map(post => (
                        <li
                            key={post.id}
                            onClick={() => onSelectPost(post.id)}
                            className={`card-gradient p-4 rounded-xl cursor-pointer transition-all ${selectedPost === post.id
                                ? "ring-4 ring-primary-400 shadow-xl"
                                : "hover:shadow-md"
                                }`}
                        >
                            <h4 className="font-bold">{post.title}</h4>
                            <p className="text-gray-600 line-clamp-2">{post.content}</p>
                        </li>
                    ))}
                </ul>
            )}
        </div>
    );
}

export default PostList;
